import random
from lib import f
def orig(a):
    r=[]
    for x in a:
        if x%2==0: r.append(x*x)
    return r
rnd = random.Random(7)
for _ in range(500):
    xs = [rnd.randint(-50, 50) for _ in range(rnd.randint(0, 12))]
    assert f(list(xs)) == orig(xs), xs
assert f([]) == []
print("ok")
